    if (count === 0) {
        st = set('1', '2', '3');
    } else if (count === 1) {
        //st = set('1', '2', '4');
        st = set('1', '2'); //Only leave 1 message
    } else if (count >= 2) {
        st = set('1', '2');
    }

    return st;
}

